def upgrade():
    connection=op.get_bind()
    folder=Path(__file__).resolve().parents[2]/'revision_materials'
    replacements={level:{i['id']:i for i in json.loads((folder/f'unit7-{level}.json').read_text())['items']} for level in OLD}
    for name,column in [('revision_tests','definition'),('revision_attempts','snapshot')]:
        table=sa.table(name,sa.column('id'),sa.column(column,sa.JSON),sa.column('begun_at',sa.DateTime),sa.column('submitted_at',sa.DateTime))
        query=sa.select(table.c.id,table.c[column])
        if name=='revision_attempts':query=query.where(table.c.begun_at.is_(None),table.c.submitted_at.is_(None))
        for identifier,definition in connection.execute(query).all():
            level=str(definition.get('level','')).lower()
            if level not in OLD:continue
            items=[];changed=False
            for item in definition.get('items',[]):
                previous=OLD[level].get(item['id'])
                current=replacements[level].get(item['id'])
                unchanged=previous and all(item.get(key)==previous.get(key) for key in ['prompt','answers','choices','groups'])
                transitional=previous and current and all(item.get(key)==current.get(key) for key in ['prompt','answers','groups']) and item.get('choices',[]) in [[],previous.get('choices',[])]
                if unchanged or transitional:
                    item=replacements[level][item['id']];changed=True
                items.append(item)
            if changed:connection.execute(table.update().where(table.c.id==identifier).values({column:{**definition,'items':items}}))

def downgrade():
    pass
